 SELECT 'SV_AD' AS SV, COUNT(*) AS OK FROM SEMANTIC_VIEW(GN_DW.SERVING.SV_AD METRICS CTR) UNION ALL SELECT 'SV_BUDGET' AS SV, COUNT(*) AS OK FROM SEMANTIC_VIEW(GN_DW.SERVING.SV_BUDGET METRICS EXEC_RATE) UNION ALL SELECT 'SV_DEV_ACHIEVEMENT' AS SV, COUNT(*) AS OK FROM SEMANTIC_VIEW(GN_DW.SERVING.SV_DEV_ACHIEVEMENT METRICS ACHIEVEMENT_RATE) UNION ALL SELECT 'SV_EVENT_PARTICIPATION' AS SV, COUNT(*) AS OK FROM SEMANTIC_VIEW(GN_DW.SERVING.SV_EVENT_PARTICIPATION METRICS DISTINCT_PARTICIPANTS) UNION ALL SELECT 'SV_MEMBER_COHORT' AS SV, COUNT(*) AS OK FROM SEMANTIC_VIEW(GN_DW.SERVING.SV_MEMBER_COHORT METRICS AVG_TENURE_DAYS) UNION ALL SELECT 'SV_MEMBER_EVENT' AS SV, COUNT(*) AS OK FROM SEMANTIC_VIEW(GN_DW.SERVING.SV_MEMBER_EVENT METRICS CAMPAIGN_STOP_MEMBER_COUNT) UNION ALL SELECT 'SV_MEMBER_FEE' AS SV, COUNT(*) AS OK FROM SEMANTIC_VIEW(GN_DW.SERVING.SV_MEMBER_FEE METRICS DISTINCT_PAYING_MEMBERS) UNION ALL SELECT 'SV_MEMBER_MONTHLY' AS SV, COUNT(*) AS OK FROM SEMANTIC_VIEW(GN_DW.SERVING.SV_MEMBER_MONTHLY METRICS AVG_PAID_FEE) UNION ALL SELECT 'SV_SERVICE' AS SV, COUNT(*) AS OK FROM SEMANTIC_VIEW(GN_DW.SERVING.SV_SERVICE METRICS DISTINCT_SEND_MEMBERS)
